urlset:
{% assign pages = site.html_pages | concat: site.posts %}
{% for page in pages %}
  {% if page.sitemap == false or page.url contains '404' or page.url contains '.xml' or page.url contains 'feed' %}
    {% continue %}
  {% endif %}

    {{ page.url | replace: 'index.html', '' | absolute_url }}

    {% if page.date %}
      {{ page.date | date_to_xmlschema }}
    {% endif %}

    {% if page.collection == 'posts' %}weekly{% else %}monthly{% endif %}
    {% if page.url == '/' or page.url == '/en/' %}1.0{% elsif page.collection == 'posts' %}0.8{% else %}0.6{% endif %}

    {% if page.ref and page.lang %}
      {% assign alternates = pages | where: "ref", page.ref %}
      {% for alt in alternates %}

      {% endfor %}
    {% endif %}

{% endfor %}
